import{_ as n,o as t,c as o,a2 as s,j as i,a}from"./chunks/framework.DNL3hc5c.js";const r="/magma/v4/library-logo.svg",f=JSON.parse('{"title":"Tempo Library Functionality","description":"","frontmatter":{},"headers":[],"relativePath":"doc/6-utility-library/tempo.library.md","filePath":"doc/6-utility-library/tempo.library.md"}'),l={name:"doc/6-utility-library/tempo.library.md"},c={class:"MathJax",jax:"SVG",style:{direction:"ltr",position:"relative"}},d={style:{overflow:"visible","min-height":"1px","min-width":"1px","vertical-align":"-0.566ex"},xmlns:"http://www.w3.org/2000/svg",width:"4.618ex",height:"2.262ex",role:"img",focusable:"false",viewBox:"0 -750 2041 1000","aria-hidden":"true"};function p(h,e,u,m,g,y){return t(),o("div",null,[e[10]||(e[10]=s('<p><img src="'+r+'" alt="Tempo Library"></p><h1 id="tempo-library-functionality" tabindex="-1">Tempo Library Functionality <a class="header-anchor" href="#tempo-library-functionality" aria-label="Permalink to &quot;Tempo Library Functionality&quot;">​</a></h1><p>While Tempo is primarily a Date-Time engine, it relies on several custom utilities under the hood to handle data structures, deep cloning, and serialization safely.</p><p>These utilities are robust enough that they are exported as public API methods for use within your own application logic.</p><p>This document serves as an index summarizing these core library features.</p><br><h2 id="_1-enumerators-enumify-enum" tabindex="-1">1. Enumerators (<code>enumify</code>, <code>Enum.*</code>) <a class="header-anchor" href="#_1-enumerators-enumify-enum" aria-label="Permalink to &quot;1. Enumerators (`enumify`, `Enum.*`)&quot;">​</a></h2><p>Tempo uses a custom utility called <code>enumify</code> to create heavily-protected, iterable enum-like objects instead of relying on native TypeScript enums.</p><p>This allows for structural typing, easy type-safe iteration via static reflection helpers (<code>Enum.keys()</code>, <code>Enum.values()</code>), and runtime safety without the overhead or compilation quirks of standard TS Enums.</p><p>It is heavily used internally for concepts like <code>Weekdays</code>, <code>Months</code>, <code>Compass cardinal points</code> and <code>Meteorological Seasons</code>.</p><p>👉 <strong><a href="./tempo.enumerators.html">Read the full Enumerators Guide</a></strong> for details on definition, methods, and a comparison with native enums.</p><br><h2 id="_2-serialization-stringify-objectify-cloneify" tabindex="-1">2. Serialization (<code>stringify</code>, <code>objectify</code>, <code>cloneify</code>) <a class="header-anchor" href="#_2-serialization-stringify-objectify-cloneify" aria-label="Permalink to &quot;2. Serialization (`stringify`, `objectify`, `cloneify`)&quot;">​</a></h2><p>Native JSON methods (<code>JSON.stringify</code> and <code>JSON.parse</code>) often fail or destructively mutate rich JavaScript data types like <code>BigInt</code>, <code>Map</code>, <code>Set</code>, <code>Symbol</code>, and <code>Date</code>.</p><p>To ensure safe data persistence across <code>localStorage</code>, <code>IndexedDB</code>, or network boundaries, Tempo implements its own serialization suite:</p><ul><li><strong><code>stringify()</code>:</strong> Safely serializes rich objects, protecting circular references and complex types.</li><li><strong><code>objectify()</code>:</strong> Safely reconstructs objects previously serialized by <code>stringify()</code>.</li><li><strong><code>cloneify()</code>:</strong> Performs a deep-copy of an object, preserving all rich data types.</li></ul><p>👉 <strong><a href="./tempo.serializers.html">Read the full Serializers Guide</a></strong> for detailed usage, benefits, and trade-offs compared to native <code>JSON</code> methods or <code>structuredClone</code>.</p><br><h2 id="_3-high-performance-push-pull-streams-reactive" tabindex="-1">3. High-Performance Push/Pull Streams (<code>Reactive</code>) <a class="header-anchor" href="#_3-high-performance-push-pull-streams-reactive" aria-label="Permalink to &quot;3. High-Performance Push/Pull Streams (`Reactive`)&quot;">​</a></h2>',19)),i("p",null,[e[2]||(e[2]=a("Tempo includes ",-1)),e[3]||(e[3]=i("code",null,"Reactive<T>",-1)),e[4]||(e[4]=a(", a bidirectional asynchronous stream primitive that unifies push-based event listeners and pull-based async iterators (",-1)),e[5]||(e[5]=i("code",null,"for await",-1)),e[6]||(e[6]=a(") with ",-1)),i("mjx-container",c,[(t(),o("svg",d,[...e[0]||(e[0]=[s('<g stroke="currentColor" fill="currentColor" stroke-width="0" transform="scale(1,-1)"><g data-mml-node="math"><g data-mml-node="mi"><path data-c="1D442" d="M740 435Q740 320 676 213T511 42T304 -22Q207 -22 138 35T51 201Q50 209 50 244Q50 346 98 438T227 601Q351 704 476 704Q514 704 524 703Q621 689 680 617T740 435ZM637 476Q637 565 591 615T476 665Q396 665 322 605Q242 542 200 428T157 216Q157 126 200 73T314 19Q404 19 485 98T608 313Q637 408 637 476Z" style="stroke-width:3;"></path></g><g data-mml-node="mo" transform="translate(763,0)"><path data-c="28" d="M94 250Q94 319 104 381T127 488T164 576T202 643T244 695T277 729T302 750H315H319Q333 750 333 741Q333 738 316 720T275 667T226 581T184 443T167 250T184 58T225 -81T274 -167T316 -220T333 -241Q333 -250 318 -250H315H302L274 -226Q180 -141 137 -14T94 250Z" style="stroke-width:3;"></path></g><g data-mml-node="mn" transform="translate(1152,0)"><path data-c="31" d="M213 578L200 573Q186 568 160 563T102 556H83V602H102Q149 604 189 617T245 641T273 663Q275 666 285 666Q294 666 302 660V361L303 61Q310 54 315 52T339 48T401 46H427V0H416Q395 3 257 3Q121 3 100 0H88V46H114Q136 46 152 46T177 47T193 50T201 52T207 57T213 61V578Z" style="stroke-width:3;"></path></g><g data-mml-node="mo" transform="translate(1652,0)"><path data-c="29" d="M60 749L64 750Q69 750 74 750H86L114 726Q208 641 251 514T294 250Q294 182 284 119T261 12T224 -76T186 -143T145 -194T113 -227T90 -246Q87 -249 86 -250H74Q66 -250 63 -250T58 -247T55 -238Q56 -237 66 -225Q221 -64 221 250T66 725Q56 737 55 738Q55 746 60 749Z" style="stroke-width:3;"></path></g></g></g>',1)])])),e[1]||(e[1]=i("mjx-assistive-mml",{unselectable:"on",display:"inline",style:{top:"0px",left:"0px",clip:"rect(1px, 1px, 1px, 1px)","-webkit-touch-callout":"none","-webkit-user-select":"none","-khtml-user-select":"none","-moz-user-select":"none","-ms-user-select":"none","user-select":"none",position:"absolute",padding:"1px 0px 0px 0px",border:"0px",display:"block",width:"auto",overflow:"hidden"}},[i("math",{xmlns:"http://www.w3.org/1998/Math/MathML"},[i("mi",null,"O"),i("mo",{stretchy:"false"},"("),i("mn",null,"1"),i("mo",{stretchy:"false"},")")])],-1))]),e[7]||(e[7]=a(" dispatch, backpressure buffering, and explicit resource management (",-1)),e[8]||(e[8]=i("code",null,"using",-1)),e[9]||(e[9]=a(").",-1))]),e[11]||(e[11]=s('<ul><li><strong>Push/Pull Duality:</strong> Seamlessly switch between event subscribers (<code>stream.on(&#39;data&#39;, cb)</code>) and async pull iteration (<code>await stream.pull()</code>, <code>for await</code>).</li><li><strong>Disposable Subscriptions:</strong> <code>stream.on()</code> returns a <code>Reactive.Subscription</code> implementing TC39 <code>Disposable</code> (<code>using sub = stream.on(...)</code>).</li><li><strong>Stream Truncation:</strong> Easily gate or bound streams via <code>stream.until(signal | promise | otherStream)</code>.</li><li><strong>Leak-Proof Finalization:</strong> Backed by <code>Finalizer</code> to ensure unclosed abandoned streams are safely reclaimed by the garbage collector.</li></ul><p>👉 <strong><a href="./tempo.reactive.html">Read the full Reactive Streams Guide</a></strong> for detailed usage, patterns, and state inspection.</p><br><h2 id="_4-deferred-promises-pledge" tabindex="-1">4. Deferred Promises (<code>Pledge</code>) <a class="header-anchor" href="#_4-deferred-promises-pledge" aria-label="Permalink to &quot;4. Deferred Promises (`Pledge`)&quot;">​</a></h2><p>Tempo provides a specialized wrapper around <code>Promise.withResolvers()</code> called <code>Pledge</code>. It is designed to simplify modern asynchronous patterns where you need to manage a promise&#39;s lifecycle externally.</p><h3 id="key-features" tabindex="-1">Key Features <a class="header-anchor" href="#key-features" aria-label="Permalink to &quot;Key Features&quot;">​</a></h3><ul><li><strong>State Tracking:</strong> Transparent access to <code>isPending</code>, <code>isResolved</code>, and <code>isRejected</code> flags.</li><li><strong>Custom Lifecycle Hooks:</strong> Support for <code>onResolve</code>, <code>onReject</code>, and <code>onSettle</code> callbacks.</li><li><strong>Immutable Shell:</strong> Once created, the Pledge instance is frozen, ensuring the promise reference cannot be swapped.</li><li><strong>Resource Management:</strong> Implements <code>Symbol.dispose</code> to automatically reject pending promises when they go out of scope, preventing deadlocks or memory leaks.</li></ul><p>👉 <strong><a href="./tempo.pledge.html">Read the full Pledge Guide</a></strong> for advanced usage with callbacks, debugging tags, and lifecycle management.</p><br><h2 id="_5-gc-safety-memory-management-weakcache-finalizer" tabindex="-1">5. GC Safety &amp; Memory Management (<code>WeakCache</code>, <code>Finalizer</code>) <a class="header-anchor" href="#_5-gc-safety-memory-management-weakcache-finalizer" aria-label="Permalink to &quot;5. GC Safety &amp; Memory Management (`WeakCache`, `Finalizer`)&quot;">​</a></h2><p>For performance-critical and memory-sensitive architectures, Tempo exports two key garbage-collection primitives:</p><ul><li><strong><code>WeakCache&lt;K, V&gt;</code>:</strong> High-performance, GC-cooperative memoization cache that allows unreferenced keys or values to be collected without memory retention.</li><li><strong><code>Finalizer</code>:</strong> Safe abstraction over <code>FinalizationRegistry</code> to register automatic teardown callbacks for timers, streams, or proxies without pinning object references.</li></ul><br><h2 id="_6-functional-evaluation-evaluate-dynamicproxy" tabindex="-1">6. Functional Evaluation (<code>evaluate</code>, <code>dynamicProxy</code>) <a class="header-anchor" href="#_6-functional-evaluation-evaluate-dynamicproxy" aria-label="Permalink to &quot;6. Functional Evaluation (`evaluate`, `dynamicProxy`)&quot;">​</a></h2><p>Tempo exports functional evaluation utilities for resolving static values, lazy suppliers, and dynamic object proxies:</p><ul><li><strong><code>evaluate(...values)</code>:</strong> Synchronously resolves candidate values or zero-argument supplier functions (<code>() =&gt; T</code>) in order, returning the first defined result (lazy coalesce with short-circuiting).</li><li><strong><code>evaluateAsync(...values)</code>:</strong> Asynchronously resolves static values, sync/async suppliers, or Promises (<code>() =&gt; Promise&lt;T&gt; | T</code>) in order with short-circuiting.</li><li><strong><code>evaluateConfig(config)</code> / <code>evaluateConfigAsync(config)</code>:</strong> Resolves <code>Evaluable</code> property suppliers on the top-level properties of a configuration dictionary.</li><li><strong><code>dynamicProxy(target)</code>:</strong> Wraps a target object with dynamic property traps that evaluate function-valued properties lazily on-access.</li><li><strong><code>Evaluable&lt;T&gt;</code> / <code>AsyncEvaluable&lt;T&gt;</code>:</strong> TypeScript utility types representing values that can be provided directly or supplied lazily via functions.</li></ul><div class="language-typescript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { evaluate, evaluateAsync, dynamicProxy } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;@magmacomputing/tempo/library&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Synchronous supplier evaluation with lazy cascading fallback (short-circuited)</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> tz</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> evaluate</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(options.timeZone, () </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> process.env.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">TZ</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;UTC&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Asynchronous supplier evaluation (e.g. secret vault / remote config)</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> apiKey</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> evaluateAsync</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(provider.key, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">async</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> () </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> vault.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">getKey</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;openai&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">));</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Dynamic proxy with lazy on-access getters</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> dynamicSettings</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> dynamicProxy</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  timeout: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  token</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: () </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> getActiveToken</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">});</span></span></code></pre></div><br><h2 id="_7-class-decorators-immutable-serializable-static" tabindex="-1">7. Class Decorators (<code>@Immutable</code>, <code>@Serializable</code>, <code>@Static</code>) <a class="header-anchor" href="#_7-class-decorators-immutable-serializable-static" aria-label="Permalink to &quot;7. Class Decorators (`@Immutable`, `@Serializable`, `@Static`)&quot;">​</a></h2><p>Tempo uses lightweight TypeScript class decorators internally to enforce immutability (<code>@Immutable</code>), register custom serialization handlers (<code>@Serializable</code>), and prevent instantiation of static-only classes (<code>@Static</code>).</p><br><h2 id="_8-exhaustive-api-reference" tabindex="-1">8. Exhaustive API Reference <a class="header-anchor" href="#_8-exhaustive-api-reference" aria-label="Permalink to &quot;8. Exhaustive API Reference&quot;">​</a></h2><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>These are isolated, standalone utility functions and classes developed internally to support our various applications. They are entirely free to use and are documented here as a convenience reference for our users.</p></div><p>While some of these utilities may be used internally by the Tempo library, many are completely independent (such as the browser and server-specific functions). They do not declare external dependencies, keeping them lightweight and portable.</p><p>The library is split into domain-specific modules:</p><ul><li><strong>Browser</strong>: Functions and classes that rely on browser APIs (e.g., <code>window</code>, <code>localStorage</code>, <code>Geolocation</code>).</li><li><strong>Server</strong>: Node.js specific utilities (e.g., file system access, server-side JWT decoding).</li><li><strong>Common</strong>: Runtime-agnostic utilities shared across all environments (<code>evaluation</code>, <code>assertion</code>, <code>coercion</code>, <code>cipher</code>, <code>json</code>, <code>calendar</code>, <code>recurrence</code>, <code>proxy</code>).</li></ul><p>You can browse the full API reference in the sidebar below this section.</p>',27))])}const b=n(l,[["render",p]]);export{f as __pageData,b as default};
